package A3;
import java.sql.*;import java.util.*;
public class StudentDao implements Dao<StudentDao.Student,String>{public record Student(String id,String name,String email,String courseId){}private final Connection c;public StudentDao(Connection c){this.c=c;}public void insert(Student s)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO student(student_id,name,email,course_id) VALUES(?,?,?,?)")){p.setString(1,s.id());p.setString(2,s.name());p.setString(3,s.email());p.setString(4,s.courseId());p.executeUpdate();}}public Optional<Student>findById(String id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT student_id,name,email,course_id FROM student WHERE student_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new Student(r.getString(1),r.getString(2),r.getString(3),r.getString(4))):Optional.empty();}}}public List<Student>findAll()throws SQLException{List<Student>out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT student_id,name,email,course_id FROM student");ResultSet r=p.executeQuery()){while(r.next())out.add(new Student(r.getString(1),r.getString(2),r.getString(3),r.getString(4)));}return out;}public void update(Student s)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE student SET name=?,email=?,course_id=? WHERE student_id=?")){p.setString(1,s.name());p.setString(2,s.email());p.setString(3,s.courseId());p.setString(4,s.id());p.executeUpdate();}}public void delete(String id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM student WHERE student_id=?")){p.setString(1,id);p.executeUpdate();}}}
